// O(n) memory: a stack of nodes
public ListNode ReverseWithStack(ListNode head) {
    if (head == null) return null;
    var stack = new Stack<ListNode>();
    for (var n = head; n != null; n = n.next) stack.Push(n);
    var newHead = stack.Pop();
    var tail = newHead;
    while (stack.Count > 0) { tail.next = stack.Pop(); tail = tail.next; }
    tail.next = null;            // the former head is now the tail; otherwise a cycle
    return newHead;
}

