public ListNode ReverseRec(ListNode head) {
    if (head == null || head.next == null) return head;   // empty or a single node
    var newHead = ReverseRec(head.next);   // the tail is reversed, its head is the new head
    head.next.next = head;                 // the former second node points back at us
    head.next = null;                      // we are now last
    return newHead;
}

